  if($('#place-detail-content').length){const detailId=Number(new URLSearchParams(location.search).get('id'));const place=getSitePlaces().find(x=>x.id===detailId);if(place){document.title=place.name+'｜映畫竹塹';const detail='<div class="detail-cover" id="place-detail-cover" role="img" aria-label="'+place.name+'"></div><div class="detail-body"><p class="eyebrow">HSINCHU CITY GUIDE / DETAIL</p><h1>'+place.name+'</h1><p class="detail-lead">'+place.desc+'</p><p>'+place.address+'<br>營業時間：'+place.hours+'</p><div class="detail-meta">'+place.area+'・'+place.type+(place.discount?'・'+place.discount:'')+'</div><div class="detail-actions"><a class="button button-dark" href="${prefix}explore.html">回到城市散策 ↗</a><a class="text-link" href="planner.html?place='+place.id+'">加入旅行計畫 <span>→</span></a></div></div>';$('#place-detail-content').html(detail);$('#place-detail-cover').css('background-image','url('+place.image+')')}else $('#place-detail-content').html('<h1>找不到這個景點</h1><p>這筆示範景點可能已刪除。</p><a class="button button-dark" href="${prefix}explore.html">回到城市散策 ↗</a>')}
  // 海報 URL 僅接受一般網頁與專案相對路徑，避免將任意協定寫入圖片樣式。
  function safeImageUrl(value,fallback){const url=String(value||'').trim();return /^(https?:\/\/|\.\.?\/|\/|[\w.-]+\.(?:png|jpe?g|webp|gif|svg)(?:[?#].*)?$)/i.test(url)?url:fallback}
  function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
  const fallbackFilmImage='https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=1200&q=85';
  function filmDetailHref(film,index){const known={'島嶼的慢鏡頭':'island-slow','窗邊的星期天':'window-sunday','風從城裡來':'wind-city','光的形狀':'shape-of-light'}[film.name];return known?`films/${known}.html`:`film-detail.html?id=${index}`}
