  if(dynamicFilm.length){const item=films[Number(detailQuery.get('id'))];if(item){dynamicFilm.find('[data-detail-title]').text(item.name);dynamicFilm.find('[data-detail-lead]').text(item.desc||'更多場次資訊請以影像博物館公告為準。');dynamicFilm.find('[data-detail-meta]').text(`${item.date||''}　${item.day||''}　${item.time||''}｜${item.genre||'城市放映'}`);dynamicFilm.find('.detail-cover').css('background-image',`url(${JSON.stringify(safeImageUrl(item.image,fallbackFilmImage))})`).attr('aria-label',item.name+'電影海報');if(item.ticket&&/^https?:\/\//i.test(item.ticket))dynamicFilm.find('[data-ticket]').attr('href',item.ticket).removeAttr('hidden');document.title=item.name+'｜映畫竹塹'}else dynamicFilm.find('[data-detail-title]').text('找不到這部電影')}
