  function initReveal(){if(observer)observer.disconnect();if(!('IntersectionObserver'in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){$('.reveal,.image-reveal').addClass('in-view');return}observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.page.active .reveal,.page.active .image-reveal').forEach(el=>observer.observe(el))}
  function goPage(page){const target=$(`[data-page-panel="${page}"]`);if(!target.length)return;$('.page').removeClass('active').attr('hidden',true);target.attr('hidden',false).addClass('active');$('.primary-nav a').removeClass('active').filter(`[data-page="${page}"]`).addClass('active');$('.primary-nav').removeClass('open');$('.menu-toggle').attr('aria-expanded','false').attr('aria-label','開啟導覽選單');history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(page==='explore')renderPlaces();if(page==='cinema')renderFilms();if(page==='events')renderNews();if(page==='planner')renderItinerary();if(page==='admin')renderAdmin(currentAdminTab);setTimeout(initReveal,40)}
