  $('.admin-mobile-menu').on('click',function(){const open=$(this).attr('aria-expanded')!=='true';$(this).attr('aria-expanded',String(open)).attr('aria-label',open?'關閉後台導覽':'開啟後台導覽');$('.admin-sidebar').toggleClass('open',open)});
