  function renderPlaces(){const area=$('#area-filter').val()||'all',query=(($('#place-search').val()||'').trim()||new URLSearchParams(location.search).get('q')||'').toLowerCase(),all=getSitePlaces();if(query&&!$('#place-search').val())$('#place-search').val(query);$('.guide-tab').each(function(){const category=$(this).data('category'),count=category==='all'?all.length:all.filter(p=>p.category===category).length;$(this).find('span').text(String(count).padStart(2,'0'))});const visible=all.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&(area==='all'||p.area===area)&&(!query||`${p.name} ${p.desc} ${p.type}`.toLowerCase().includes(query)));$('#place-grid').html(visible.length?visible.map(p=>{const liked=favorites.has(String(p.id)),detail=({1:'museum.html',2:'places/dongmen-market.html',3:'places/or-arts.html',4:'places/hsinchu-park.html',5:'places/or-coffee.html',6:'places/shanfang.html'})[p.id]||'place-detail.html?id='+p.id;return `<article class="place-card reveal"><div class="place-image" style="background-image:url('${p.image||places[0].image}')" role="img" aria-label="${p.name}"><span class="place-type">${p.type||p.category}</span><button class="favorite-button${liked?' active':''}" aria-label="收藏${p.name}" aria-pressed="${liked}" data-favorite="${p.id}">${liked?'♥':'♡'}</button></div><div class="place-body"><span class="place-area">${p.area}　/　${p.rating||'在地推薦'}</span><h3>${p.name}</h3><p>${p.desc||''}</p><div class="place-details"><span>◷ ${p.hours||'依店家公告'}</span><span class="place-actions"><a href="${detail}">看介紹 ↗</a><button data-add-stop="${p.id}">＋ 行程</button></span></div></div></article>`}).join(''):'<p class="empty-results">找不到符合條件的地點，試試其他關鍵字。</p>');initReveal()}
  // 優惠列表和詳情各自使用獨立頁面與獨立資料集。
  function renderOffers(){const visible=offers.filter(o=>o.status!=="草稿"&&o.status!=="draft");$("#offers-list").html(visible.map(o=>{const i=offers.indexOf(o),detail=({101:"offers/or-crafts.html?id=101",102:"offers/shanfang.html?id=102",103:"offers/autumn-coffee.html?id=103"})[o.id]||"offer-detail.html?id="+o.id;return `<article class="place-card reveal"><div class="place-image" style="background-image:url('${o.image||places[0].image}')" role="img" aria-label="${o.merchant}優惠圖片"><span class="place-type">${o.area}・期間限定</span></div><div class="place-body"><span class="place-area">${o.merchant}　/　優惠至 ${o.endDate||"依店家公告"}</span><h3>${o.title}</h3><p>${o.desc||""}</p><div class="place-details"><strong>${o.discount||"店家限定優惠"}</strong><span class="place-actions"><a href="${detail}">優惠詳情 ↗</a></span></div></div></article>`}).join("")||"<p class=empty-results>目前沒有上架中的店家優惠。</p>");initReveal()}
