  function newCaptcha(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';captchaValue=Array.from({length:5},()=>chars[Math.floor(Math.random()*chars.length)]).join('');$('#captcha-code').text(captchaValue)}
