  // 管理員權限以模組與操作類型保存；固定 admin 帳號永遠保有完整權限。
  const adminPermissionModules=[['dashboard','總覽儀表板'],['places','景點與店家'],['films','本週映演'],['news','消息與活動'],['offers','店家優惠'],['routes','推薦行程'],['admins','管理員管理'],['permissions','權限設定'],['members','會員管理'],['settings','網站設定']];
