  function defaultAdminPermissions(role){const rights={};adminPermissionModules.forEach(([key])=>{rights[key]={view:false,create:false,edit:false,delete:false}});rights.dashboard.view=true;if(role==='viewer'){['places','films','news','offers','routes'].forEach(key=>{rights[key].view=true})}if(role==='content-editor'){['places','films','news','offers','routes'].forEach(key=>{rights[key]={view:true,create:true,edit:true,delete:true}});rights.admins={view:true,create:true,edit:true,delete:true};rights.permissions={view:true,create:false,edit:true,delete:false}}else if(role==='news-editor'){['films','news'].forEach(key=>{rights[key]={view:true,create:true,edit:true,delete:false}})}return rights}
  const fixedAdminAccount={id:'root-admin',account:'admin',name:'系統管理員',email:'admin@yinghua.tw',role:'super',fixed:true};
  function fullAdminPermissions(){const rights={};adminPermissionModules.forEach(([key])=>{rights[key]={view:true,create:true,edit:true,delete:true}});return rights}
  function getAdminAccounts(){let saved=JSON.parse(localStorage.getItem('yinghuaAdminAccounts')||'null');if(!Array.isArray(saved)){saved=[{...fixedAdminAccount,permissions:fullAdminPermissions()},{id:'demo-editor',account:'editor',name:'內容編輯',email:'editor@yinghua.tw',role:'content-editor',permissions:defaultAdminPermissions('content-editor')},{id:'demo-news',account:'news-editor',name:'消息編輯',email:'news@yinghua.tw',role:'news-editor',permissions:defaultAdminPermissions('news-editor')}];localStorage.setItem('yinghuaAdminAccounts',JSON.stringify(saved))}const root=saved.find(a=>a.fixed||a.id==='root-admin')||{...fixedAdminAccount,permissions:fullAdminPermissions()};Object.assign(root,fixedAdminAccount,{permissions:fullAdminPermissions()});return [root,...saved.filter(a=>!a.fixed&&a.id!=='root-admin')]}
