  function adminCan(module,action='view'){const user=activeAdmin();return !!(user&&(user.fixed||user.permissions&&user.permissions[module]&&user.permissions[module][action]===true))}
  function applyAdminPermissions(){const user=activeAdmin();$('.admin-user').each(function(){const $box=$(this);$box.find('b').first().text(user.name);$box.find('small').first().text(user.account+'｜模擬管理員')});$('.admin-nav[data-admin-tab]').each(function(){const key=$(this).data('admin-tab');$(this).toggle(adminCan(key,'view'))});$('.quick-actions [data-admin-tab]').each(function(){const key=$(this).data('admin-tab');$(this).prop('disabled',!adminCan(key,'create'))});$('.admin-content a[href$="-add.html"]').each(function(){const file=$(this).attr('href').split('/').pop(),key=file.startsWith('admin-')?'admins':file.startsWith('place-')?'places':file.startsWith('offer-')?'offers':file.startsWith('film-')?'films':file.startsWith('news-')?'news':'routes';$(this).toggle(adminCan(key,'create'))});$('.admin-content button.table-actions').each(function(){const action=$(this).text().trim(),capability=action==='編輯'?'edit':action==='刪除'?'delete':'view';$(this).toggle(adminCan(currentAdminTab,capability))});const addButtons={places:'#new-place',news:'#add-news'};Object.entries(addButtons).forEach(([key,selector])=>$(selector).toggle(adminCan(key,'create')));$('.admin-content [data-permission-action]').each(function(){const $item=$(this),action=$item.data('permission-action'),module=$item.data('permission-module')||currentAdminTab;if(!adminCan(module,action))$item.prop('disabled',true).attr('aria-disabled','true')});$('.admin-sidebar').each(function(){const $sidebar=$(this);if(!$sidebar.find('.admin-session-switch').length){const $label=$('<label class="admin-session-switch"><span>模擬登入身分</span><select aria-label="切換模擬登入管理員"></select></label>');adminAccounts.forEach(a=>$label.find('select').append($('<option>').val(a.id).text(a.name+'（'+a.account+'）')));$label.find('select').val(user.id).on('change',function(){localStorage.setItem('yinghuaActiveAdminId',this.value);location.reload()});$sidebar.append($label)}})}
  function populatePlaceForm(item){if(!item)return;const $sample=$('#demo-place-select');if($sample.length&&!$sample.find(`option[value="${item.id}"]`).length)$sample.append($('<option>').val(item.id).text(item.name+'（目前編輯項目）'));if($sample.length)$sample.val(String(item.id));$('#place-name-input').val(item.name||'');$('#place-category-input').val(item.category||'景點');$('#place-area-input').val(item.area||'北區');$('#place-hours-input').val(item.hours||'');$('#place-address-input').val(item.address||'');$('#place-desc-input').val(item.desc||'')}
  const editPlaceId=Number(new URLSearchParams(location.search).get('id'));
