    const source=module==='admins'?adminAccounts:module==='films'?films:module==='news'?news:module==='offers'?offers:(JSON.parse(localStorage.getItem(routeStoreKey)||'null')||[{id:1,title:'一日光影・老城散步',theme:'影像與舊城',desc:'影像博物館、東門市場與新竹公園。',places:[1,2,4]},{id:2,title:'午後公園與咖啡',theme:'慢活散策',desc:'在公園與街角咖啡之間慢慢走。',places:[4,5,6]}]);
