      if(module==='admins'){const duplicate=updated.some((item,index)=>index!==id-1&&(String(item.account||'').toLowerCase()===String(values.account||'').trim().toLowerCase()||String(item.email||'').toLowerCase()===String(values.email||'').trim().toLowerCase()));if(duplicate){toast('帳號或電子郵件已存在，請更換後再儲存');return}values.account=String(values.account||'').trim();values.name=String(values.name||'').trim();values.email=String(values.email||'').trim()}
