  $(document).on('click','.admin-content .table-actions',function(){
    const action=$(this).text().trim(),module=currentAdminTab,row=$(this).closest('tr'),rowId=Number($(this).attr('data-record-id'))||row.index()+1,name=row.find('td').eq(0).text().trim(),permission=action==='編輯'?'edit':action==='刪除'?'delete':'view';
    if(!adminCan(module,permission)){toast('目前管理員沒有執行此操作的權限');return}
    if(action==='編輯'){
      const file={places:'place-edit.html',offers:'offer-edit.html',films:'film-edit.html',news:'news-edit.html',routes:'route-edit.html',admins:'admin-edit.html'}[module];
      if(module==='admins'){const target=adminAccounts.find(a=>String(a.id)===String($(this).attr('data-account-id')));if(!target||target.fixed){toast('固定系統管理員 admin 不可編輯');return}}
      if(file){const id=module==='places'?(Number($(this).attr('data-edit-place'))||rowId):rowId;location.href=file+'?id='+id}return
    }
    if(action==='查看'){const email=row.find('td').eq(1).text().trim();toast(`${name}｜${email}｜會員資料示範`);return}
    if(action==='刪除'){
      if(module==='admins'){const target=adminAccounts.find(a=>String(a.id)===String($(this).attr('data-account-id')));if(!target||target.fixed){toast('固定系統管理員 admin 不可刪除');return}}
      if(!confirm('確定刪除「'+name+'」？刪除後無法復原。'))return;
      if(module==='places'){const id=Number($(this).data('delete-place'));adminPlaces=adminPlaces.filter(p=>p.id!==id);localStorage.setItem('yinghuaAdminPlaces',JSON.stringify(adminPlaces))}
      if(module==='films'){films=films.filter(x=>x.name!==name);localStorage.setItem('yinghuaAdminFilms',JSON.stringify(films))}
      if(module==='news'){news=news.filter(x=>x.title!==name);localStorage.setItem('yinghuaAdminNews',JSON.stringify(news))}
      if(module==='offers'){offers=offers.filter(x=>x.title!==name);localStorage.setItem('yinghuaAdminOffers',JSON.stringify(offers))}
      if(module==='routes'){const items=JSON.parse(localStorage.getItem(routeStoreKey)||'[]');localStorage.setItem(routeStoreKey,JSON.stringify(items.filter(x=>x.title!==name)))}
      if(module==='admins'){const accountId=String($(this).attr('data-account-id'));adminAccounts=adminAccounts.filter(a=>String(a.id)!==accountId);localStorage.setItem('yinghuaAdminAccounts',JSON.stringify(adminAccounts));if(localStorage.getItem('yinghuaActiveAdminId')===accountId){localStorage.setItem('yinghuaActiveAdminId','root-admin');toast('已刪除管理員並切回固定系統管理員')}else toast('已刪除管理員「'+name+'」');renderAdmin('admins');return}
      row.remove();toast('已刪除「'+name+'」')
    }
  });

